use kimo_core::{effects::Frame,shards::{self,ShardBurst},three_d::Camera};use serde_json::json;
fn render(height:f64,light:[f64;3],strength:f64)->Frame{let e:ShardBurst=serde_json::from_value(json!({"count":1,"origin":[0,0,-height],"speed":0,"size_min":100,"size_max":100,"spin":0,"dof":0,"gravity":0,"seed":7,"contact_shadow":strength,"shadow_reach":220,"light":light})).unwrap();let mut f=Frame::new(640,360);shards::render(&e,&mut f,0.3,&Camera::default(),25.,2.);f}
fn metrics(a:&Frame,b:&Frame)->(usize,f32,f64,f64){let mut n=0;let mut peak=0f32;let(mut sum,mut x,mut y)=(0f64,0f64,0f64);for i in 0..a.w*a.h{let d=(a.d[i*4+3]-b.d[i*4+3]).max(0.);if d>1e-6{n+=1;}peak=peak.max(d);sum+=d as f64;x+=d as f64*(i%a.w) as f64;y+=d as f64*(i/a.w) as f64;}(n,peak,x/sum.max(1e-9),y/sum.max(1e-9))}
#[test]fn contact_shadow_visible_fades_and_reverses(){let l=[-0.5,-0.6,-0.62];let near=metrics(&render(20.,l,0.6),&render(20.,l,0.));let far=metrics(&render(180.,l,0.6),&render(180.,l,0.));assert!(near.0>1000&&near.1>0.4);assert!(far.0>1000&&far.1>0.05&&far.1<near.1);assert!(far.2>near.2&&far.3>near.3);let l=[0.5,0.6,-0.62];let flip=metrics(&render(180.,l,0.6),&render(180.,l,0.));assert!(flip.0>1000&&flip.2<320.&&flip.3<180.);}
#[test]fn shadow_zero_repeatable(){let a=render(20.,[-0.5,-0.6,-0.62],0.);let b=render(20.,[-0.5,-0.6,-0.62],0.);assert_eq!(a.d,b.d);}
#[test]fn occluded_receiver_suppresses_shadows_and_mesh(){use std::sync::Arc;shards::EXT_OCC.with(|m|*m.borrow_mut()=Some(Arc::new(vec![1.;640*360])));let f=render(20.,[-0.5,-0.6,-0.62],0.6);assert!(f.d.iter().all(|x|*x==0.));}
#[test]fn black_shadow_composites_without_brightening(){let a=render(20.,[-0.5,-0.6,-0.62],0.6);let b=render(20.,[-0.5,-0.6,-0.62],0.);let mut darker=0;for i in 0..a.w*a.h{for j in 0..3{let on=a.d[i*4+j]*a.d[i*4+3]+0.65*(1.-a.d[i*4+3]);let off=b.d[i*4+j]*b.d[i*4+3]+0.65*(1.-b.d[i*4+3]);assert!(on<=off+1e-6);if off-on>0.01{darker+=1;}}}assert!(darker>1000);}
